{"file_path":"src/parse.js","content":"// Parsing of an election description read from standard input.

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

class ParseError extends Error {
  constructor(message) {
    super(message)
    this.name = 'ParseError'
  }
}

function fail(line, message) {
  if (line === null) {
    throw new ParseError(`error: ${message}`)
  }
  throw new ParseError(`error: line ${line}: ${message}`)
}

/**
 * Parses the raw election text into a candidate list and ballot list.
 * Throws ParseError with a fully formatted message on any failure.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidates = null // array of names, in declared order
  const candidateSet = new Set()
  const ballots = [] // { count, prefs: [name...] }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const word0 = words[0]

    if (word0 === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (words.length < 2) {
        fail(lineNo, 'expected candidates <name>...')
      }
      const names = words.slice(1)
      candidates = []
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          fail(lineNo, `invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          fail(lineNo, `candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
    } else if (word0 === 'ballot') {
      if (candidates === null) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (words.length < 3) {
        fail(lineNo, 'expected ballot <count> <candidate>...')
      }
      const countWord = words[1]
      if (!COUNT_RE.test(countWord)) {
        fail(lineNo, 'count must be a positive integer')
      }
      const count = Number(countWord)
      const prefs = []
      const seen = new Set()
      for (const name of words.slice(2)) {
        if (!candidateSet.has(name)) {
          fail(lineNo, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          fail(lineNo, `candidate ${name} is repeated`)
        }
        seen.add(name)
        prefs.push(name)
      }
      ballots.push({ count, prefs })
    } else {
      fail(lineNo, `unknown directive ${word0}`)
    }
  }

  if (candidates === null) {
    fail(null, 'no candidates')
  }

  return { candidates, ballots }
}

export { ParseError }
"}

