/**
 * Runs the instant-runoff count.
 * Returns { rounds, winner } where rounds is an array of
 * { counts: Map<name, votes>, exhausted, eliminated } for continuing
 * candidates as of the start of that round, and winner is the winning
 * candidate name or null.
 */
export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const rounds = []
  const history = [] // array of Map(name -> votes) for each round, continuing candidates only
  let winner = null

  while (true) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      let target = null
      for (const name of ballot.prefs) {
        if (continuing.has(name)) {
          target = name
          break
        }
      }
      if (target === null) {
        exhausted += ballot.count
      } else {
        votes.set(target, votes.get(target) + ballot.count)
      }
    }

    let activeTotal = 0
    for (const v of votes.values()) activeTotal += v

    history.push(votes)

    if (activeTotal === 0) {
      rounds.push({ counts: votes, exhausted, eliminated: null })
      winner = null
      break
    }

    let majorityWinner = null
    for (const [name, v] of votes) {
      if (v * 2 > activeTotal) {
        majorityWinner = name
        break
      }
    }

    if (majorityWinner !== null) {
      rounds.push({ counts: votes, exhausted, eliminated: null })
      winner = majorityWinner
      break
    }

    // Determine elimination: fewest votes this round, tie-broken by history.
    let minVotes = Infinity
    for (const v of votes.values()) if (v < minVotes) minVotes = v
    let tied = [...continuing].filter((name) => votes.get(name) === minVotes)

    if (tied.length > 1) {
      for (const roundVotes of history) {
        if (tied.length <= 1) break
        let roundMin = Infinity
        for (const name of tied) {
          const v = roundVotes.get(name)
          if (v !== undefined && v < roundMin) roundMin = v
        }
        const allEqual = tied.every((name) => roundVotes.get(name) === roundMin)
        if (!allEqual) {
          tied = tied.filter((name) => roundVotes.get(name) === roundMin)
        }
      }
    }

    let eliminated
    if (tied.length === 1) {
      eliminated = tied[0]
    } else {
      eliminated = tied.reduce((a, b) => (a > b ? a : b))
    }

    rounds.push({ counts: votes, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}
"}

